class Solution {
public:
    vector<int> shortestAlternatingPaths(int n, vector<vector<int>>& redEdges, vector<vector<int>>& blueEdges) {
        vector<vector<pair<int,int>>> adj(n);
        for (auto& e : redEdges)  adj[e[0]].push_back({e[1], 0});
        for (auto& e : blueEdges) adj[e[0]].push_back({e[1], 1});

        const int INF = 1e9;
        // dist[node][color]: 0 = last edge red, 1 = last edge blue, 2 = start (no edge yet)
        vector<vector<int>> dist(n, vector<int>(3, INF));
        dist[0][2] = 0;

        queue<tuple<int,int,int>> q; // (node, lastColor, distance)
        q.push({0, 2, 0});

        while (!q.empty()) {
            auto [u, c, d] = q.front(); q.pop();
            if (d > dist[u][c]) continue;
            for (auto& pr : adj[u]) {
                int v  = pr.first;
                int ec = pr.second; // edge color
                if (c == 2 || ec != c) { // start state: any color; otherwise must differ
                    if (d + 1 < dist[v][ec]) {
                        dist[v][ec] = d + 1;
                        q.push({v, ec, d + 1});
                    }
                }
            }
        }

        vector<int> ans(n);
        for (int i = 0; i < n; i++) {
            int best = min({dist[i][0], dist[i][1], dist[i][2]});
            ans[i] = (best >= INF) ? -1 : best;
        }
        return ans;
    }
};
